package com.school.management.controller;
import com.school.management.entity.SchoolClass; import com.school.management.repository.SchoolClassRepository; import com.school.management.repository.StudentRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/classes") public class ClassController {
 private final SchoolClassRepository classes; private final StudentRepository students;
 public ClassController(SchoolClassRepository classes,StudentRepository students){this.classes=classes;this.students=students;}
 @GetMapping public List<Map<String,Object>> all(){return classes.findAll().stream().sorted(Comparator.comparing(SchoolClass::getName)).map(c->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.getClassCode());m.put("name",c.getName());m.put("teacher",c.getTeacher());m.put("students",students.findAll().stream().filter(s->c.getName().equalsIgnoreCase(s.getClassName())).count());m.put("room",c.getRoom());m.put("schedule",c.getSchedule());m.put("subject",c.getSubject());return m;}).toList();}
 @PostMapping public ResponseEntity<?> create(@RequestBody SchoolClass c){if(c.getName()==null||c.getName().isBlank())throw new IllegalArgumentException("Class name is required");if(classes.findByNameIgnoreCase(c.getName()).isPresent())throw new IllegalArgumentException("Class already exists");c.setId(null);c.setClassCode("CLS-"+String.format("%03d",classes.count()+1));return ResponseEntity.status(HttpStatus.CREATED).body(classes.save(c));}
 @PutMapping("/{name}") public SchoolClass update(@PathVariable String name,@RequestBody SchoolClass input){SchoolClass c=classes.findByNameIgnoreCase(name).orElseThrow(()->new NoSuchElementException("Class not found"));c.setTeacher(input.getTeacher());c.setRoom(input.getRoom());c.setSchedule(input.getSchedule());c.setSubject(input.getSubject());return classes.save(c);}
 @DeleteMapping("/{name}") public ResponseEntity<?> delete(@PathVariable String name){SchoolClass c=classes.findByNameIgnoreCase(name).orElseThrow(()->new NoSuchElementException("Class not found"));classes.delete(c);return ResponseEntity.noContent().build();}
}
